mapper.sql:
FROM ( SELECT M.INPT_ATMC_BIZ_DSCD , (SELECT MAX(CASE WHEN H.AI_INPT_ACVT_CD = '40' THEN '재추출' WHEN H.AI_INPT_ACVT_CD = '70' THEN '재심사' ELSE X.AI_INPT_CMN_CD_NM END) KEEP( DENSE_RANK FIRST ORDER BY H.AI_INPT_PRG_SRNO DESC )AS AI_INPT_CMN_CD_NM FROM CSPD008TH H , CSPD112TI X WHERE H.INPT_MST_SRNO = M.INPT_MST_SRNO AND (H.AI_INPT_ACVT_STS_CD IN ('60', '70', '100') OR H.AI_INPT_ACVT_CD IN ('40', '70')) AND X.AI_INPT_GRP_CD(+) = '300' AND X.AI_INPT_CMN_CD(+) = H.AI_INPT_ACVT_STS_CD ) AS WRR_INFO , M.AI_INPT_PROS_CD , M.AI_INPT_ACVT_CD , NVL(EP.XPBY_COL_CTR_CUCD, IP.TDOC_RCP_CUCD)AS XPBY_COL_CTR_CUCD , NVL(EP.XPBY_COL_AM ,IP.TDOC_RCP_AM) AS XPBY_COL_AM , NVL(EP.CUS_KORL_NM ,IP.CUS_KORL_NM) AS CUS_KORL_NM , NVL(EP.CSNO ,IP.CSNO) AS CSNO , M.TOTALTEXT_AI_INPT_RST_CD , M.ITM_INPT_AI_INPT_RST_CD , M.SAFEWATCH_AI_INPT_RST_CD , M.INPT_MST_SRNO , M.INPT_RCP_DT , M.ACTL_FX_REFNO , M.FX_REFNO_SRNO , M.AI_INPT_IMG_KEY_NO ,(-- DetectionID SELECT MAX(FILT_DTCT_NO) KEEP( DENSE_RANK FIRST ORDER BY AI_INPT_PRG_SRNO DESC ) AS FILT_DTCT_NO FROM CSPD007TL WHERE INPT_MST_SRNO = M.INPT_MST_SRNO ) AS FILT_DTCT_NO
,( SELECT LST_DB_CHG_DTM FROM CSPD001TM WHERE INPT_MST_SRNO = M.INPT_MST_SRNO AND TO_NUMBER(AI_INPT_ACVT_CD) < 80 ) AS PRE_AI_INPT_PRG_SRNO
, CASE WHEN TO_NUMBER(AI_INPT_ACVT_CD) < 80 THEN (TO_DATE(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_DATE(SUBSTR(REPLACE(M.LST_DB_CHG_DTM ,'-',''),1,14),'YYYYMMDDHH24MISS')) * 24 * 60 ELSE 0 END AS DELAY_TIME
, (SELECT MAX(CASE WHEN AI_INPT_ACVT_STS_CD IN ('20', '60') AND AI_INPT_PRC_OPI_TXT IS NOT NULL THEN '21' ELSE AI_INPT_ACVT_STS_CD END) KEEP( DENSE_RANK FIRST ORDER BY AI_INPT_PRG_SRNO DESC ) AS INPT_TASK_ID FROM CSPD008TH WHERE INPT_MST_SRNO = M.INPT_MST_SRNO ) AS STATUS
, Q.AI_SYS_INPT_PRG_STCD AS Q_PRG_STCD FROM CSPD001TM M , CSPD201TM EP -- 수출테이블 , CSPD202TM IP -- 수입테이블 , CSPD900TI Q WHERE M.AI_INSPE_ENO = #{userId} AND (M.AI_INPT_ACVT_CD NOT IN ('80', '90') OR (M.AI_INPT_ACVT_CD IN ('80','90') AND M.PAPS_RE_SCAN_NED_YN = 'Y')) AND M.PAPS_RE_SCAN_CMPL_YN IS NULL AND M.ACTL_FX_REFNO = EP.FX_ACNO(+) AND M.FX_REFNO_SRNO = EP.XPO_CVRG_MK_SQ(+) AND M.ACTL_FX_REFNO = IP.FX_ACNO(+) AND M.FX_REFNO_SRNO = IP.TDOC_RCP_SRNO(+) AND M.INPT_MST_SRNO = Q.INPT_MST_SRNO(+)
AND M.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
AND M.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
AND M.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '')
) A LEFT OUTER JOIN CSPD112TI E ON E.AI_INPT_GRP_CD = '150' AND E.AI_INPT_CMN_CD = A.INPT_ATMC_BIZ_DSCD LEFT OUTER JOIN CSPD112TI F ON F.AI_INPT_GRP_CD = '280' AND F.AI_INPT_CMN_CD = A.AI_INPT_PROS_CD LEFT OUTER JOIN CSPD112TI G ON G.AI_INPT_GRP_CD = '290' AND G.AI_INPT_CMN_CD = A.AI_INPT_ACVT_CD LEFT OUTER JOIN CSPD112TI H ON H.AI_INPT_GRP_CD = '170' AND H.AI_INPT_CMN_CD = A.TOTALTEXT_AI_INPT_RST_CD LEFT OUTER JOIN CSPD112TI I ON I.AI_INPT_GRP_CD = '170' AND I.AI_INPT_CMN_CD = A.ITM_INPT_AI_INPT_RST_CD LEFT OUTER JOIN CSPD112TI J ON J.AI_INPT_GRP_CD = '170' AND J.AI_INPT_CMN_CD = A.SAFEWATCH_AI_INPT_RST_CD WHERE 1=1
AND A.CSNO = #{aiInptCsno}
